/// Run a program for a tiny stack machine and return the final stack (bottom
/// first), or None if the program fails.
/// An instruction is an opcode, optionally followed by one space and an integer
/// argument; an integer argument is an optional '-' then 1 to 9 ASCII digits.
/// Execution starts at instruction 0 and stops at "halt" or when the program
/// counter equals len(program). Opcodes:
/// - "push N": push N. "pop": discard the top. "dup": push a copy of the top.
///   "swap": exchange the top two values.
/// - "add", "sub", "mul", "div", "mod": pop b, then pop a, push a op b. "div"
///   truncates toward zero and "mod" takes the sign of a, so a == b * div + mod.
/// - "jmp T": continue at instruction T. "jz T": pop a value; if it is 0 continue
///   at instruction T, otherwise at the next instruction.
/// - "halt": stop.
/// Return None if: an opcode is unknown (opcodes are case sensitive); an argument is
/// missing, extra or malformed (only push, jmp and jz take one); an instruction needs
/// more values than the stack holds; div or mod divides by 0; a jump target T is
/// outside 0..len(program) inclusive; or more than 1000 instructions would execute
/// (a 1001st instruction is about to run). Values stay well inside 32 bits.
/// >>> run_vm(vec![String::from("push 7"), String::from("push -2"), String::from("div"), String::from("push 7"), String::from("push -2"), String::from("mod")])
/// Some(vec![-3, 1])
/// >>> run_vm(vec![String::from("push 3"), String::from("dup"), String::from("jz 6"), String::from("push -1"), String::from("add"), String::from("jmp 1"), String::from("halt")])
/// Some(vec![0])
fn run_vm(program: Vec<String>) -> Option<Vec<isize>> {
    let mut stack: Vec<isize> = Vec::new();
    let mut pc: usize = 0;
    let mut steps = 0;
    while pc != program.len() {
        if steps == 1000 {
            return None;
        }
        steps += 1;
        let words: Vec<&str> = program[pc].split(' ').collect();
        let op = words[0];
        let need = match op {
            "push" | "jmp" | "halt" => 0,
            "pop" | "dup" | "jz" => 1,
            "swap" | "add" | "sub" | "mul" | "div" | "mod" => 2,
            _ => return None,
        };
        if stack.len() < need {
            return None;
        }
        let mut arg: isize = 0;
        if op == "push" || op == "jmp" || op == "jz" {
            if words.len() != 2 {
                return None;
            }
            arg = parse_arg(words[1])?;
            if op != "push" && (arg < 0 || arg > program.len() as isize) {
                return None;
            }
        } else if words.len() != 1 {
            return None;
        }
        pc += 1;
        match op {
            "push" => stack.push(arg),
            "pop" => {
                stack.pop();
            }
            "dup" => stack.push(stack[stack.len() - 1]),
            "swap" => {
                let n = stack.len();
                stack.swap(n - 1, n - 2);
            }
            "jmp" => pc = arg as usize,
            "jz" => {
                if stack.pop()? == 0 {
                    pc = arg as usize;
                }
            }
            "halt" => break,
            _ => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                if (op == "div" || op == "mod") && b == 0 {
                    return None;
                }
                stack.push(match op {
                    "add" => a + b,
                    "sub" => a - b,
                    "mul" => a * b,
                    "div" => a / b,
                    _ => a % b,
                });
            }
        }
    }
    Some(stack)
}

fn parse_arg(word: &str) -> Option<isize> {
    let digits = word.strip_prefix('-').unwrap_or(word);
    if digits.is_empty() || digits.len() > 9 || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    word.parse().ok()
}
